  /// <No documentation available>
  static const int PATH_ACCESSOR_TYPE_BOOL = 6;

  /// <No documentation available>
  static const int PATH_ACCESSOR_TYPE_NULL = 7;

  /// <No documentation available>
  static const int PATH_ACCESSOR_TYPE_OBJECT = 8;

  /// <No documentation available>
  static const int PATH_ACCESSOR_TYPE_ARRAY = 9;

